-- MediHelp: USMLE Step 1 - Physiology (200 MCQs)
-- Idempotent Migration: Locates existing "Physiology" topic and ensures a clean state.

DO $$
DECLARE
    v_topic_id UUID;
BEGIN
    -- 1. Find existing "Physiology" Topic for USMLE Step 1
    SELECT id INTO v_topic_id FROM public.topics 
    WHERE title = 'Physiology' AND usmle_step = 1 
    LIMIT 1;

    -- 2. If not found, create it (fallback)
    IF v_topic_id IS NULL THEN
        INSERT INTO public.topics (title, slug, usmle_step, "order")
        VALUES ('Physiology', 'physiology-step-1', 1, 10)
        RETURNING id INTO v_topic_id;
    END IF;

    -- 3. CLEAN UP: Remove existing MCQs for this topic to ensure a clean state
    DELETE FROM public.mcqs WHERE topic_id = v_topic_id;

    -- 4. Insert MCQs (1-200)
    INSERT INTO public.mcqs (topic_id, question, options, correct_index, explanation)
    VALUES
    -- Q1-Q10
    (v_topic_id, 'A 65-year-old man with chronic hypertension develops concentric left ventricular hypertrophy. Which variable was most likely chronically increased?', to_jsonb(ARRAY['Preload', 'Afterload', 'Contractility', 'Venous compliance', 'Ejection fraction']), 1, 'Chronic hypertension increases afterload, causing pressure overload and concentric hypertrophy.'),
    (v_topic_id, 'A healthy person suddenly stands after lying down for several hours. Which change occurs first?', to_jsonb(ARRAY['Increased venous return', 'Increased cerebral perfusion', 'Decreased venous return', 'Decreased sympathetic tone', 'Increased stroke volume']), 2, 'Standing causes venous pooling in the legs, decreasing venous return, stroke volume, and transiently arterial pressure.'),
    (v_topic_id, 'Following sudden standing, baroreceptor firing in the carotid sinus initially:', to_jsonb(ARRAY['Increases', 'Decreases', 'Stays unchanged', 'Doubles', 'Becomes independent of pressure']), 1, 'The fall in arterial pressure decreases stretch, so carotid sinus firing decreases.'),
    (v_topic_id, 'A drug causes arteriolar vasoconstriction through α1 stimulation. Which immediate reflex response is expected?', to_jsonb(ARRAY['Tachycardia', 'Bradycardia', 'Increased renin release', 'Decreased stroke volume', 'Decreased MAP']), 1, 'α1-mediated vasoconstriction raises MAP, causing reflex bradycardia through the baroreceptor reflex.'),
    (v_topic_id, 'A patient with hemorrhagic shock has cool extremities and tachycardia. Which hemodynamic profile is most likely?', to_jsonb(ARRAY['Increased preload, increased cardiac output', 'Decreased preload, decreased cardiac output', 'Increased preload, decreased TPR', 'Increased stroke volume, decreased sympathetic tone', 'Increased central venous pressure']), 1, 'Blood loss lowers preload, which lowers stroke volume and cardiac output.'),
    (v_topic_id, 'In early septic shock, which hemodynamic finding is most characteristic?', to_jsonb(ARRAY['Increased systemic vascular resistance', 'Decreased systemic vascular resistance', 'Decreased skin blood flow', 'Markedly reduced mixed venous oxygen saturation in all cases', 'Bradycardia']), 1, 'Early septic shock is often a warm shock state with low SVR due to vasodilation.'),
    (v_topic_id, 'Which determinant most directly increases myocardial oxygen demand?', to_jsonb(ARRAY['Decreased heart rate', 'Decreased contractility', 'Increased wall tension', 'Increased venous compliance', 'Decreased systolic pressure']), 2, 'Myocardial oxygen demand increases with heart rate, contractility, and wall tension.'),
    (v_topic_id, 'Left ventricular coronary perfusion occurs primarily during:', to_jsonb(ARRAY['Systole', 'Early systole', 'Diastole', 'Isovolumetric contraction', 'Atrial systole only']), 2, 'Left ventricular contraction compresses intramyocardial vessels during systole, so perfusion is greatest in diastole.'),
    (v_topic_id, 'A patient receives rapid IV isotonic saline. According to Frank-Starling physiology, stroke volume should:', to_jsonb(ARRAY['Decrease', 'Increase', 'Stay unchanged', 'Fall to zero', 'Become independent of preload']), 1, 'Increased venous return raises preload and increases stroke volume through the Frank-Starling mechanism.'),
    (v_topic_id, 'In systolic heart failure, which change is most expected?', to_jsonb(ARRAY['Decreased end-systolic volume', 'Increased ejection fraction', 'Increased end-systolic volume', 'Increased contractility', 'Decreased end-diastolic volume always']), 2, 'Poor contractility leaves more blood in the ventricle after systole, increasing ESV.'),

    -- Q11-Q20
    (v_topic_id, 'At high altitude, the immediate trigger for hyperventilation is primarily:', to_jsonb(ARRAY['Increased PaCO2', 'Decreased PaO2 sensed by peripheral chemoreceptors', 'Increased CSF bicarbonate', 'Increased central chemoreceptor activity due to alkalosis', 'Increased hemoglobin concentration']), 1, 'Low arterial oxygen stimulates carotid and aortic body chemoreceptors.'),
    (v_topic_id, 'The initial acid-base change at high altitude is:', to_jsonb(ARRAY['Respiratory acidosis', 'Respiratory alkalosis', 'Metabolic acidosis', 'Metabolic alkalosis', 'No change']), 1, 'Hyperventilation lowers PaCO2, causing respiratory alkalosis.'),
    (v_topic_id, 'A patient with opioid overdose hypoventilates. Which arterial blood gas pattern is most likely?', to_jsonb(ARRAY['Low PaCO2, high pH', 'High PaCO2, low pH', 'Low PaCO2, low pH', 'High PaCO2, high pH', 'Normal PaCO2, low pH']), 1, 'Hypoventilation causes CO2 retention and respiratory acidosis.'),
    (v_topic_id, 'Central chemoreceptors primarily respond to:', to_jsonb(ARRAY['Arterial oxygen tension', 'CSF hydrogen ion concentration generated from CO2', 'Serum sodium', 'Serum bicarbonate directly', 'Aortic arch stretch']), 1, 'CO2 diffuses into CSF and generates H+, which stimulates central chemoreceptors.'),
    (v_topic_id, 'A pulmonary embolus causes which regional ventilation-perfusion abnormality?', to_jsonb(ARRAY['Low V/Q', 'High V/Q', 'Normal V/Q', 'Right-to-left shunt', 'Low alveolar oxygen with high perfusion']), 1, 'Ventilation persists but perfusion falls, creating high V/Q and increased dead space.'),
    (v_topic_id, 'An obstructed bronchus causes which V/Q abnormality in the affected region?', to_jsonb(ARRAY['High V/Q', 'Low V/Q approaching shunt', 'Increased dead space only', 'No change', 'Infinite V/Q']), 1, 'Perfusion remains but ventilation is reduced, creating low V/Q.'),
    (v_topic_id, 'In emphysema, lung compliance is typically:', to_jsonb(ARRAY['Decreased', 'Increased', 'Unchanged', 'Zero', 'Lower than in fibrosis']), 1, 'Emphysema destroys elastic tissue, increasing lung compliance.'),
    (v_topic_id, 'In pulmonary fibrosis, total lung capacity is typically:', to_jsonb(ARRAY['Increased', 'Decreased', 'Unchanged', 'Increased after bronchodilator only', 'Higher than residual volume only']), 1, 'Fibrosis causes a restrictive defect with low TLC.'),
    (v_topic_id, 'Quiet inspiration primarily depends on contraction of the:', to_jsonb(ARRAY['Internal intercostals', 'Diaphragm', 'Rectus abdominis', 'Transversus abdominis', 'SCM']), 1, 'The diaphragm is the main muscle of quiet inspiration.'),
    (v_topic_id, 'During inspiration, intrapleural pressure becomes:', to_jsonb(ARRAY['More positive', 'More negative', 'Equal to atmospheric pressure', 'Zero', 'Unchanged']), 1, 'Expansion of the thoracic cavity makes intrapleural pressure more negative.'),

    -- Q21-Q30
    (v_topic_id, 'Diarrhea most commonly causes which acid-base disorder?', to_jsonb(ARRAY['High anion gap metabolic acidosis', 'Non-anion gap metabolic acidosis', 'Respiratory acidosis', 'Respiratory alkalosis', 'Metabolic alkalosis']), 1, 'Diarrhea causes bicarbonate loss, producing non-anion gap metabolic acidosis.'),
    (v_topic_id, 'Persistent vomiting most commonly causes:', to_jsonb(ARRAY['Metabolic acidosis', 'Metabolic alkalosis', 'Respiratory acidosis', 'Respiratory alkalosis', 'High anion gap acidosis']), 1, 'Vomiting causes loss of gastric H+, producing metabolic alkalosis.'),
    (v_topic_id, 'Diabetic ketoacidosis causes which breathing pattern?', to_jsonb(ARRAY['Cheyne-Stokes', 'Biot', 'Kussmaul', 'Apneustic', 'Ataxic']), 2, 'DKA produces high anion gap metabolic acidosis with compensatory deep rapid breathing.'),
    (v_topic_id, 'Renin release from juxtaglomerular cells is stimulated by:', to_jsonb(ARRAY['Increased afferent arteriole pressure', 'Decreased afferent arteriole pressure', 'Increased NaCl delivery to macula densa', 'ANP', 'Hypervolemia']), 1, 'Low renal perfusion stimulates renin release.'),
    (v_topic_id, 'Angiotensin II preferentially constricts which renal arteriole?', to_jsonb(ARRAY['Afferent arteriole', 'Efferent arteriole', 'Interlobar artery only', 'Vasa recta only', 'Both equally at physiologic levels']), 1, 'At physiologic levels, angiotensin II preferentially constricts the efferent arteriole.'),
    (v_topic_id, 'Inulin clearance is equal to:', to_jsonb(ARRAY['Renal plasma flow', 'Renal blood flow', 'Glomerular filtration rate', 'Filtration fraction', 'Urine flow rate']), 2, 'Inulin is freely filtered and neither secreted nor reabsorbed, so its clearance equals GFR.'),
    (v_topic_id, 'PAH clearance approximates:', to_jsonb(ARRAY['GFR', 'Renal plasma flow', 'Renal blood flow', 'Urine flow', 'Filtration fraction']), 1, 'PAH is filtered and heavily secreted, so its clearance approximates renal plasma flow.'),
    (v_topic_id, 'Glucose appears in urine when:', to_jsonb(ARRAY['GFR falls below normal', 'Filtered load exceeds transport maximum', 'Tubular secretion rises', 'Aldosterone falls', 'ADH rises']), 1, 'Glucosuria occurs when the filtered load exceeds the proximal tubule’s Tm.'),
    (v_topic_id, 'The thick ascending limb of the loop of Henle is normally impermeable to:', to_jsonb(ARRAY['Sodium', 'Chloride', 'Potassium', 'Water', 'Urea']), 3, 'The thick ascending limb reabsorbs solute but is impermeable to water, helping dilute tubular fluid.'),
    (v_topic_id, 'ADH increases water permeability in the collecting duct by inserting:', to_jsonb(ARRAY['Aquaporin-1', 'Aquaporin-2', 'ENaC', 'ROMK', 'SGLT2']), 1, 'ADH acts on V2 receptors, leading to insertion of AQP2 into the apical membrane.'),

    -- Q31-Q40
    (v_topic_id, 'Primary hyperaldosteronism typically causes:', to_jsonb(ARRAY['Hyperkalemia and metabolic acidosis', 'Hypokalemia and metabolic alkalosis', 'Hyponatremia and acidosis', 'Hypercalcemia and alkalosis', 'Hypermagnesemia and acidosis']), 1, 'Aldosterone increases Na reabsorption and K/H secretion.'),
    (v_topic_id, 'In prerenal azotemia, urine sodium is usually:', to_jsonb(ARRAY['High', 'Low', 'Equal to plasma sodium', 'Fixed at 140 mEq/L', 'Unrelated to volume status']), 1, 'The kidney avidly conserves sodium in prerenal states, so urine Na is usually low.'),
    (v_topic_id, 'Gastrin is secreted by which cells?', to_jsonb(ARRAY['G cells', 'D cells', 'I cells', 'S cells', 'Chief cells']), 0, 'G cells in the antrum secrete gastrin.'),
    (v_topic_id, 'Histamine stimulates gastric acid secretion by acting on which receptor on parietal cells?', to_jsonb(ARRAY['H1', 'H2', 'M3', 'V1', 'α1']), 1, 'Histamine acts on H2 receptors on parietal cells to increase acid secretion.'),
    (v_topic_id, 'Cholecystokinin is released primarily in response to:', to_jsonb(ARRAY['Acid in the duodenum', 'Fat and amino acids in the duodenum', 'Distention of the stomach', 'Hypoglycemia', 'Hyperosmolarity in the colon']), 1, 'CCK is released by I cells in response to fats and amino acids.'),
    (v_topic_id, 'Secretin primarily stimulates:', to_jsonb(ARRAY['Gastric acid secretion', 'Pancreatic bicarbonate secretion', 'Gallbladder contraction', 'Insulin secretion', 'Colonic sodium absorption']), 1, 'Secretin is released in response to duodenal acid and stimulates bicarbonate secretion.'),
    (v_topic_id, 'Pernicious anemia impairs absorption of vitamin B12 in the:', to_jsonb(ARRAY['Duodenum', 'Jejunum', 'Terminal ileum', 'Colon', 'Stomach']), 2, 'Vitamin B12-intrinsic factor complexes are absorbed in the terminal ileum.'),
    (v_topic_id, 'A lesion of the ventromedial hypothalamus is most likely to cause:', to_jsonb(ARRAY['Aphagia', 'Hyperphagia', 'Hyperthermia only', 'Central diabetes insipidus', 'Loss of thirst only']), 1, 'The ventromedial hypothalamus is the satiety center; lesions cause overeating.'),
    (v_topic_id, 'PTH decreases phosphate reabsorption primarily in which nephron segment?', to_jsonb(ARRAY['Collecting duct', 'Thick ascending limb', 'Proximal tubule', 'Distal convoluted tubule', 'Descending limb']), 2, 'PTH reduces phosphate reabsorption in the proximal tubule.'),
    (v_topic_id, 'Insulin-dependent glucose uptake occurs mainly via which transporter?', to_jsonb(ARRAY['GLUT1', 'GLUT2', 'GLUT3', 'GLUT4', 'SGLT1']), 3, 'GLUT4 is insulin-dependent and found in skeletal muscle and adipose tissue.'),

    -- Q41-Q50
    (v_topic_id, 'Glucagon primarily acts on which organ to increase glycogenolysis?', to_jsonb(ARRAY['Skeletal muscle', 'Liver', 'Adipose tissue only', 'Brain', 'Pancreatic beta cells']), 1, 'Glucagon acts primarily on the liver, not skeletal muscle.'),
    (v_topic_id, 'ADH is synthesized in the:', to_jsonb(ARRAY['Posterior pituitary', 'Anterior pituitary', 'Hypothalamus', 'Adrenal medulla', 'Pineal gland']), 2, 'ADH is synthesized in hypothalamic nuclei and released from the posterior pituitary.'),
    (v_topic_id, 'Milk ejection during breastfeeding is mediated by:', to_jsonb(ARRAY['Prolactin', 'Oxytocin', 'Estrogen', 'Progesterone', 'FSH']), 1, 'Oxytocin causes contraction of myoepithelial cells, producing milk letdown.'),
    (v_topic_id, 'Ovulation is triggered by a surge in:', to_jsonb(ARRAY['FSH', 'LH', 'Prolactin', 'Progesterone', 'hCG']), 1, 'A midcycle LH surge triggers ovulation.'),
    (v_topic_id, 'Sertoli cells are primarily stimulated by:', to_jsonb(ARRAY['LH', 'FSH', 'Prolactin', 'Testosterone only from circulation', 'hCG']), 1, 'FSH acts on Sertoli cells, supporting spermatogenesis.'),
    (v_topic_id, 'Leydig cells primarily respond to:', to_jsonb(ARRAY['FSH', 'LH', 'Prolactin', 'Oxytocin', 'Inhibin']), 1, 'LH stimulates Leydig cells to produce testosterone.'),
    (v_topic_id, 'A cerebellar hemisphere lesion is most likely to cause:', to_jsonb(ARRAY['Resting tremor', 'Contralateral spasticity', 'Ipsilateral ataxia', 'Flaccid paralysis', 'Aphasia']), 2, 'Cerebellar lesions produce ipsilateral coordination deficits.'),
    (v_topic_id, 'A dorsal column lesion most impairs:', to_jsonb(ARRAY['Pain and temperature', 'Vibration and proprioception', 'Motor strength', 'Taste', 'Olfaction']), 1, 'Dorsal columns transmit vibration, proprioception, and fine touch.'),
    (v_topic_id, 'Spinothalamic fibers cross in the:', to_jsonb(ARRAY['Medulla', 'Spinal cord', 'Pons', 'Midbrain', 'Cerebellum']), 1, 'Spinothalamic fibers cross in the spinal cord, usually within 1–2 segments of entry.'),
    (v_topic_id, 'An upper motor neuron lesion most classically causes:', to_jsonb(ARRAY['Fasciculations', 'Flaccid paralysis', 'Hyperreflexia', 'Severe early muscle atrophy', 'Loss of neuromuscular transmission']), 2, 'UMN lesions cause hyperreflexia, spasticity, and weakness.'),

    -- Q51-Q60
    (v_topic_id, 'In myasthenia gravis, the primary defect is at the:', to_jsonb(ARRAY['Presynaptic motor neuron', 'Postsynaptic neuromuscular junction membrane', 'Muscle sarcomere', 'Dornal horn', 'Basal ganglia']), 1, 'Myasthenia gravis involves antibodies against postsynaptic nicotinic ACh receptors.'),
    (v_topic_id, 'Hypokalemia causes skeletal muscle weakness primarily because it:', to_jsonb(ARRAY['Depolarizes the membrane', 'Hyperpolarizes the membrane', 'Increases calcium release', 'Inhibits actin synthesis', 'Increases acetylcholine release']), 1, 'Low extracellular K+ makes the membrane more negative, reducing excitability.'),
    (v_topic_id, 'The earliest immediate energy source for a 100-meter sprint is:', to_jsonb(ARRAY['Fatty acid oxidation', 'Protein catabolism', 'Stored ATP and phosphocreatine', 'Ketone oxidation', 'Hepatic gluconeogenesis']), 2, 'Short explosive activity first relies on ATP and phosphocreatine.'),
    (v_topic_id, 'During intense exercise, skeletal muscle arterioles dilate primarily due to:', to_jsonb(ARRAY['Increased parasympathetic stimulation', 'Local metabolic factors', 'Reduced CO2 production', 'Decreased adenosine', 'Increased α1 stimulation']), 1, 'Active muscle dilates due to adenosine, K+, H+, CO2, lactate, and other metabolites.'),
    (v_topic_id, 'The major mode of heat loss during heavy exercise in a hot environment is:', to_jsonb(ARRAY['Radiation', 'Conduction', 'Evaporation', 'Convection', 'Respiration only']), 2, 'In hot environments, evaporation of sweat is the main mechanism of heat loss.'),
    (v_topic_id, 'Sweat glands are innervated by:', to_jsonb(ARRAY['Parasympathetic cholinergic fibers', 'Sympathetic adrenergic fibers', 'Sympathetic cholinergic fibers', 'Somatic motor fibers', 'Vagal afferents']), 2, 'Sweat glands are unusual because they are innervated by sympathetic cholinergic fibers.'),
    (v_topic_id, 'A patient acclimatizing to heat develops increased sweating efficiency. Which change is most likely?', to_jsonb(ARRAY['More sodium lost in sweat', 'Less sodium lost in sweat', 'Lower aldosterone', 'Lower plasma volume', 'Lower ADH']), 1, 'Heat acclimatization increases aldosterone effect, causing less sodium loss in sweat.'),
    (v_topic_id, 'A patient with SIADH has which urine characteristic?', to_jsonb(ARRAY['Dilute urine', 'Concentrated urine', 'Glucose-rich urine', 'Alkaline urine only', 'Protein-rich urine only']), 1, 'Excess ADH causes water retention and inappropriately concentrated urine.'),
    (v_topic_id, 'A patient with nephrogenic diabetes insipidus will respond to desmopressin by:', to_jsonb(ARRAY['Markedly increasing urine osmolality', 'Slightly decreasing urine flow only always', 'Showing little or no response', 'Developing severe hyponatremia immediately', 'Stopping thirst']), 2, 'In nephrogenic DI, kidneys are unresponsive to ADH, so desmopressin has minimal effect.'),
    (v_topic_id, 'The filtration fraction is calculated as:', to_jsonb(ARRAY['RPF / GFR', 'GFR / RPF', 'Urine flow / GFR', 'GFR / urine flow', 'RBF / RPF']), 1, 'Filtration fraction = GFR / renal plasma flow.'),

    -- Q61-Q70
    (v_topic_id, 'A patient with unilateral renal artery stenosis has high renin. Which nephron structure senses distal NaCl delivery?', to_jsonb(ARRAY['Juxtaglomerular cells', 'Principal cells', 'Macula densa', 'Podocytes', 'Mesangial cells']), 2, 'The macula densa senses tubular NaCl delivery and helps regulate renin release.'),
    (v_topic_id, 'A patient with volume depletion has increased proximal tubule sodium reabsorption. Which force best favors this?', to_jsonb(ARRAY['Increased peritubular capillary hydrostatic pressure', 'Decreased peritubular capillary oncotic pressure', 'Increased peritubular capillary oncotic pressure', 'Decreased filtration fraction only', 'Increased Bowman''s space pressure']), 2, 'Volume depletion increases FF, which raises peritubular oncotic pressure, favoring reabsorption.'),
    (v_topic_id, 'A patient with respiratory acidosis develops renal compensation. Which process increases over time?', to_jsonb(ARRAY['Bicarbonate excretion', 'Hydrogen ion secretion', 'Renin suppression only', 'Glucose filtration', 'Potassium reabsorption only']), 1, 'In chronic respiratory acidosis, kidneys increase H+ secretion and bicarbonate retention.'),
    (v_topic_id, 'A patient with chronic vomiting develops metabolic alkalosis. Which renal response is limited by volume depletion?', to_jsonb(ARRAY['Bicarbonate excretion', 'Potassium secretion', 'Urea filtration', 'Creatinine production', 'Water excretion only']), 0, 'Volume depletion promotes bicarbonate retention, sustaining contraction alkalosis.'),
    (v_topic_id, 'A patient with heart failure has elevated ADH and RAAS activity. Which change most directly promotes edema?', to_jsonb(ARRAY['Decreased capillary hydrostatic pressure', 'Increased plasma oncotic pressure', 'Increased capillary hydrostatic pressure', 'Decreased interstitial hydrostatic pressure only', 'Increased lymph drainage beyond filtration']), 2, 'In heart failure, elevated venous pressure increases capillary hydrostatic pressure, promoting edema.'),
    (v_topic_id, 'The major determinant of glomerular filtration across the filtration barrier is:', to_jsonb(ARRAY['Plasma sodium alone', 'Net filtration pressure and filtration coefficient', 'Urine specific gravity', 'Distal sodium delivery only', 'Collecting duct permeability only']), 1, 'GFR depends on Kf and the net filtration pressure.'),
    (v_topic_id, 'A patient with nephrotic syndrome has severe edema. One major reason is:', to_jsonb(ARRAY['Increased plasma oncotic pressure', 'Decreased plasma oncotic pressure', 'Increased arterial oxygen content', 'Decreased venous pressure', 'Decreased glomerular permeability to protein']), 1, 'Heavy protein loss lowers plasma oncotic pressure, favoring edema.'),
    (v_topic_id, 'A patient with chronic liver disease develops edema and ascites partly because of reduced synthesis of:', to_jsonb(ARRAY['Fibrinogen only', 'Albumin', 'Creatinine', 'Insulin', 'Erythropoietin']), 1, 'Low albumin lowers plasma oncotic pressure and contributes to edema/ascites.'),
    (v_topic_id, 'A patient with complete fasting for 48 hours is most dependent on which process to maintain blood glucose?', to_jsonb(ARRAY['Glycogen synthesis', 'Glycogenolysis only', 'Gluconeogenesis', 'Lipogenesis', 'Ketolysis only']), 2, 'After prolonged fasting, liver glycogen is depleted and gluconeogenesis becomes the major source of glucose.'),
    (v_topic_id, 'The brain can begin using which substrate significantly during prolonged starvation?', to_jsonb(ARRAY['Fatty acids only', 'Ketone bodies', 'Lactate only', 'Triglycerides', 'Cholesterol']), 1, 'During prolonged starvation, the brain adapts to use ketone bodies.'),

    -- Q71-Q80
    (v_topic_id, 'A woman in the luteal phase of the menstrual cycle has elevated basal body temperature due mainly to:', to_jsonb(ARRAY['Estrogen', 'Progesterone', 'FSH', 'LH', 'Prolactin']), 1, 'Progesterone increases basal body temperature after ovulation.'),
    (v_topic_id, 'Theca interna cells primarily produce:', to_jsonb(ARRAY['Progesterone only', 'Androgens', 'Prolactin', 'hCG', 'Inhibin only']), 1, 'Theca interna cells produce androgens, which granulosa cells aromatize to estrogens.'),
    (v_topic_id, 'Granulosa cells primarily convert androgens to estrogens via:', to_jsonb(ARRAY['5α-reductase', 'Aromatase', 'MAO', 'COMT', 'Tyrosine hydroxylase']), 1, 'Granulosa cells use aromatase to produce estrogens.'),
    (v_topic_id, 'Human chorionic gonadotropin in early pregnancy helps maintain the:', to_jsonb(ARRAY['Follicular phase', 'Corpus luteum', 'Endometrial shedding', 'LH surge', 'Pituitary gonadotrophs only']), 1, 'hCG maintains the corpus luteum, which continues progesterone production early in pregnancy.'),
    (v_topic_id, 'A pregnant woman has increased plasma volume and increased GFR. Serum creatinine is therefore often:', to_jsonb(ARRAY['Higher than normal', 'Lower than normal', 'Unchanged exactly', 'Equal to BUN', 'Zero']), 1, 'Pregnancy increases renal plasma flow and GFR, often lowering serum creatinine.'),
    (v_topic_id, 'A patient with a lesion in Broca area will most likely have:', to_jsonb(ARRAY['Fluent speech with poor comprehension', 'Nonfluent speech with intact comprehension', 'Pure motor paralysis only', 'Complete deafness', 'Pure visual agnosia']), 1, 'Broca aphasia causes nonfluent, effortful speech with relatively preserved comprehension.'),
    (v_topic_id, 'A lesion in Wernicke area most likely causes:', to_jsonb(ARRAY['Nonfluent aphasia', 'Fluent aphasia with impaired comprehension', 'Dysarthria only', 'Pure alexia only', 'Bilateral blindness']), 1, 'Wernicke aphasia causes fluent but nonsensical speech with poor comprehension.'),
    (v_topic_id, 'The primary motor cortex is located in the:', to_jsonb(ARRAY['Postcentral gyrus', 'Precentral gyrus', 'Superior temporal gyrus', 'Occipital lobe', 'Inferior parietal lobule']), 1, 'The precentral gyrus contains primary motor cortex.'),
    (v_topic_id, 'The primary somatosensory cortex is located in the:', to_jsonb(ARRAY['Precentral gyrus', 'Postcentral gyrus', 'Inferior frontal gyrus', 'Superior temporal gyrus', 'Occipital pole']), 1, 'The postcentral gyrus contains primary somatosensory cortex.'),
    (v_topic_id, 'Damage to the hippocampus most strongly impairs:', to_jsonb(ARRAY['Procedural memory', 'New declarative memory formation', 'Language comprehension', 'Visual acuity', 'Motor planning only']), 1, 'The hippocampus is critical for forming new declarative memories.'),

