    (v_topic_id, 'A patient with bilateral amygdala damage would most likely have impaired:', to_jsonb(ARRAY['Fine motor control', 'Fear conditioning', 'Proprioception', 'Language production', 'Primary vision']), 1, 'The amygdala is central to fear and emotional salience.'),
    (v_topic_id, 'The stretch reflex is mediated by which receptor?', to_jsonb(ARRAY['Golgi tendon organ', 'Muscle spindle', 'Pacinian corpuscle', 'Free nerve ending', 'Ruffini ending']), 1, 'The muscle spindle senses stretch and triggers the stretch reflex.'),
    (v_topic_id, 'Golgi tendon organs respond primarily to:', to_jsonb(ARRAY['Muscle length', 'Muscle tension', 'Vibration only', 'Temperature', 'Pain']), 1, 'Golgi tendon organs sense tension in tendons.'),
    (v_topic_id, 'A lesion of lower motor neurons most classically causes:', to_jsonb(ARRAY['Hyperreflexia', 'Spasticity', 'Fasciculations', 'Babinski sign', 'Increased tone']), 2, 'LMN lesions cause fasciculations, hyporeflexia, flaccidity, and atrophy.'),
    (v_topic_id, 'A patient with Brown-Séquard syndrome has a left hemicord lesion. Which finding is expected below the lesion?', to_jsonb(ARRAY['Contralateral loss of vibration', 'Ipsilateral loss of motor function', 'Bilateral pain loss only', 'Contralateral motor loss only', 'Ipsilateral pain loss beginning immediately']), 1, 'A hemicord lesion causes ipsilateral corticospinal and dorsal column loss and contralateral pain/temp loss below the lesion.'),
    (v_topic_id, 'Type I skeletal muscle fibers are characterized by:', to_jsonb(ARRAY['Fast contraction, low myoglobin', 'Slow contraction, high oxidative capacity', 'Fast glycolytic metabolism only', 'Low mitochondrial content', 'Rapid fatigue']), 1, 'Type I fibers are slow-twitch oxidative, fatigue resistant, and rich in mitochondria/myoglobin.'),
    (v_topic_id, 'During skeletal muscle contraction, calcium binds to:', to_jsonb(ARRAY['Myosin', 'Actin directly', 'Troponin C', 'Tropomyosin', 'Titin']), 2, 'Calcium binds troponin C, shifting tropomyosin and allowing actin-myosin interaction.'),
    (v_topic_id, 'In cardiac muscle, the plateau phase of the action potential is primarily due to:', to_jsonb(ARRAY['Fast Na influx only', 'Calcium influx through L-type channels', 'Chloride influx', 'Potassium influx', 'Sodium-potassium pump activity']), 1, 'The cardiac plateau phase is due mainly to Ca2+ influx through L-type calcium channels.'),
    (v_topic_id, 'Pacemaker cells in the SA node depolarize spontaneously during phase 4 primarily because of:', to_jsonb(ARRAY['Fast sodium channels', 'Funny current (If) and calcium currents', 'Chloride currents only', 'Troponin activation', 'Potassium influx']), 1, 'SA node automaticity depends on the funny current and Ca currents.'),
