    (v_topic_id, 'A patient with complete AV block has a ventricular escape rhythm. Compared with the SA node, this escape rhythm is generally:', to_jsonb(ARRAY['Faster', 'Slower', 'Identical', 'Absent', 'More responsive to vagal tone only']), 1, 'Distal pacemakers fire more slowly than the SA node.'),
    (v_topic_id, 'A patient has severe aortic regurgitation. Pulse pressure is likely:', to_jsonb(ARRAY['Narrow', 'Wide', 'Zero', 'Normal', 'Fixed regardless of lesion']), 1, 'Aortic regurgitation causes increased systolic and reduced diastolic pressure, creating wide pulse pressure.'),
